def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = [False] * (n + 1)
        for l, r in offers:
            duration = r - l + 1
            if duration >= x:
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break
                if can_accept:
                    for day in range(l, r + 1):
                        occupied[day] = True

        count = sum(occ for occ in occupied[1:n+1] if occ)
        results.append(str(count))

    return '\n'.join(results) + '\n'


