    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    # Check if any number is divisible by k (shouldn't happen based on problem statement)
    for x in a:
        if x % k == 0:
            return "NO\n"

    # State: tuple of sorted numbers
    # Try to reach state (1,)
    from functools import lru_cache

    initial = tuple(sorted(a))
    found_path = None

    @lru_cache(maxsize=None)
    def can_reach(target):
        if target == (1,):
            return True, []
        if len(target) == 0:
            return False, []

        # Try all pairs
        for i in range(len(target) - 1):
            for j in range(i + 1, len(target)):
                x, y = target[i], target[j]
                new_val = f(x + y)
                new_state = tuple(sorted(target[:i]) + (new_val,) + target[i+1:j] + target[j+1:])
                if len(new_state) == 1 and new_state[0] == 1:
                    return True, [(x, y)]
                if len(new_state) > 0:
                    success, path = can_reach(new_state)
                    if success:
                        return True, [(x, y)] + path
        return False, []

    reached, operations = can_reach(initial)

    if not reached or len(operations) != n - 1:
        return "NO\n"

    return "YES\n" + "\n".join(f"{x} {y}" for x, y in operations) + "\n"


