    MOD = 1000000007

    # Identify free positions and fixed values
    fixed_values = set()
    free_positions = []

    for i in range(n):
        if a[i] == -1:
            free_positions.append(i + 1)  # 1-indexed position
        else:
            fixed_values.add(a[i])

    # Identify available values
    available_values = set()
    for v in range(1, n + 1):
        if v not in fixed_values:
            available_values.add(v)

    m = len(free_positions)
    k = 0
    # Count free positions where their value is also available
    # These are positions that COULD form a fixed point
    for pos in free_positions:
        if pos in available_values:
            k += 1

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    def combination(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = fact[r] * fact[n - r] % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    # Apply inclusion-exclusion
    result = 0
    for j in range(k + 1):
        term = combination(k, j) * fact[m - j] % MOD
        if j % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result)

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True

