    if n <= 2:
        return "0"

    # dp[i][j] = maximum points we can get from subarray a[i..j]
    # when reducing it (removing all elements between i and j)
    dp = [[0] * n for _ in range(n)]

    # length represents the number of elements in the range minus 1
    # We iterate from range size 2 (i.e., 3 elements: i, i+1, i+2+length-1)
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i, j):
                # Split at k: left part [i, k], right part [k+1, j]
                # When we process these subarrays, a[i] and a[j] become adjacent to elements being removed
                # The gain from this merge is min(a[i], a[j])
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k+1][j] + min(a[i], a[j]))

    return str(dp[0][n-1])

