def solution(input_data):
    # Parse the board
    chocolates = set()
    lines = input_data.strip().split('\n')
    for r in range(5):
        cells = lines[r].split()
        for c, cell in enumerate(cells):
            if cell == 'O':
                chocolates.add((r, c))

    # Memoization for the game state
    memo = {}

    def generate_moves(current_chocolates):
        """Generate all possible moves from the current position"""
        directions = [
            (0, 1), (0, -1),  # horizontal
            (1, 0), (-1, 0),  # vertical (in our coordinate system)
            (1, 1), (-1, -1)  # diagonals
        ]
        moves = []

        for pos in current_chocolates:
            for dr, dc in directions:
                # Find all consecutive chocolates in this direction
                path = [pos]
                curr = pos
                count = 0

                # Extend up to 5 steps in this direction
                for _ in range(5):
                    nxt = (curr[0] + dr, curr[1] + dc)
                    if nxt in current_chocolates:
                        path.append(nxt)
                        curr = nxt
                        count += 1
                    else:
                        break

                # A move can be any non-empty subset of this path
                if len(path) > 1:
                    chunk_size = 1
                    while True:
                        path_subset = tuple(path[max(0, len(path)-chunk_size):])
                        move_set = set(path_subset)
                        if move_set:
                            moves.add(tuple(sorted(move_set)))
                            chunk_size += 1
                        else:
                            break

        return list(moves)

    def can_win(chocolates):
        """Check if current player can win from this state"""
        if chocolates in memo:
            return memo[chocolates]

        if not chocolates:
            memo[chocolates] = False
            return False

        moves = generate_moves(chocolates)

        # If no moves available, current player loses
        if not moves:
            memo[chocolates] = False
            return False

        # If there's any move that leads to opponent losing, current player wins
        for move in moves:
            remaining = tuple(sorted(set(chocolates) - move))
            if not can_win(remaining):
                memo[chocolates] = True
                return True

        memo[chocolates] = False
        return False

    # Karlsson goes first
    result = can_win(tuple(sorted(chocolates)))
    return "Karlsson\n" if result else "Lillebror\n"

