def nCr_mod(n, r, MOD):
    if r < 0 or r > n:
        return 0
    return nCr_mod_fast(n, r, MOD)

def nCr_mod_fast(n, r, MOD):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    numerator = 1
    denominator = 1

    for i in range(r):
        numerator = (numerator * (n - i)) % MOD
        denominator = (denominator * (i + 1)) % MOD

    return (numerator * pow(denominator, MOD - 2, MOD)) % MOD

