def solution(s):
    """
    Count numbers in [l, r] that are both:
    1. Prime (Peter's lucky numbers)
    2. Sum of two positive squares (Bob's lucky numbers)

    For primes: p = a² + b² with a,b ≥ 1 iff p = 2 or p ≡ 1 (mod 4)
    """
    parts = s.strip().split()
    if len(parts) < 2:
        return "0\n"
    l, r = int(parts[0]), int(parts[1])

    if l > r or l < 1 or r < 1:
        return "0\n"

    # sieving primes up to sqrt(r)
    sqrt_r = int(r**0.5) + 1
    if sqrt_r < 2:
        return "0\n"

    is_small = bytearray([1]) * sqrt_r
    if sqrt_r >= 1:
        is_small[0] = 0
    if sqrt_r >= 2:
        is_small[1] = 0

    limit = int(sqrt_r**0.5) + 1
    for i in range(2, limit):
        if is_small[i]:
            is_small[i*i:sqrt_r:i] = bytearray([0]) * len(is_small[i*i:sqrt_r:i])

    small_primes = [i for i in range(sqrt_r) if is_small[i]]

    # segmented sieve over [l, r]
    n = r - l + 1
    is_prime = bytearray([1]) * n

    if l == 1:
        if n > 0:
            is_prime[0] = 0

    for p in small_primes:
        start = ((l + p - 1) // p) * p
        if start < p * p and start < l:
            start = p * p

        idx = start - l
        if idx >= n:
            continue

        for j in range(idx, n, p):
            is_prime[j] = 0

    # Count primes p where p == 2 or p % 4 == 1
    count = 0
    for i in range(n):
        if is_prime[i]:
            p = l + i
            if p == 2 or p % 4 == 1:
                count += 1

    return str(count) + "\n"

