class LiChaoTree:
    def __init__(self, min_x, max_x):
        self.min_x = min_x
        self.max_x = max_x
        self.data = {}  # Dynamically created nodes
        self.reference = {}  # Track (a,b) for each node

    def get_root(self):
        if self.data == {}:
            self.data[1] = Node()
        return self.data[1]

    def __getitem__(self, key):
        if key not in self.data:
            self.data[key] = Node()
        return self.data[key]

    def __setitem__(self, key, value):
        self.data[key] = value

    def add_line(self, line):
        """Add a line to the Li Chao Tree"""
        node = self.get_root()
        self.reference.setdefault(line, 0)

        while node is not None:
            if line and line[0] * (node.mid if hasattr(node, 'mid') else (self.min_x + self.max_x)//2) + line[1] > node.line[0] * node.mid + node.line[1]:
                # Swap lines
                node.line, line = line, node.line

            node.xl = (node.min_x + self.max_x) // 2
            node.xr = (node.min_x + self.max_x) // 2
            node.mid = (self.min_x + self.max_x) // 2

            if line is not None:
                if line > node.line:
                    node.line = line

            node.xlo = (node.xl + self.min_x) // 2
