    print(solution("17 97 41 37 11\n"))

from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [len(self.graph[u]) for u in range(self.n)]
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    edges = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        v, u, w = parts[0] - 1, parts[1] - 1, parts[2]
        edges.append((v, u, w))

    s = 0
    t = n + m + 1
    dinic = Dinic(t + 1)

    total_edge_weight = 0

    for i, (v, u, w) in enumerate(edges):
        edge_node = i + 1
        dinic.add_edge(s, edge_node, w)
        total_edge_weight += w

        dinic.add_edge(edge_node, m + v + 1, float('inf'))
        dinic.add_edge(edge_node, m + u + 1, float('inf'))

    for i, wi in enumerate(a):
        vertex_node = m + i + 1
        dinic.add_edge(vertex_node, t, wi)

    max_flow_result = dinic.max_flow(s, t)
    result = total_edge_weight - max_flow_result
    return str(result)

